#include <stdio.h>
#include <stdlib.h>
#include <libpq-fe.h>

int find_user_id(PGconn *conn, const char *email) {
  char sql[256];
  snprintf(sql, sizeof sql, "SELECT id FROM users WHERE email = '%s'", email);
  PGresult *res = PQexec(conn, sql);
  if (PQntuples(res) == 0) return 0;
  return atoi(PQgetvalue(res, 0, 0));
}

