#include <stdio.h>
#include <stdlib.h>
#include <libpq-fe.h>

int find_user_id(PGconn *conn, const char *email) {
  const char *params[1] = { email };
  PGresult *res = PQexecParams(conn,
      "SELECT id FROM users WHERE email = $1",
      1, NULL, params, NULL, NULL, 0);
  int id = -1;
  if (PQresultStatus(res) == PGRES_COMMAND_OK) {
    id = PQntuples(res) == 0 ? 0 : atoi(PQgetvalue(res, 0, 0));
  } else {
    fprintf(stderr, "find_user_id: %s", PQresultErrorMessage(res));
  }
  PQclear(res);
  return id;
}
